using System.Drawing;using System.Text.Json;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectEnvironment;
public sealed class SnapshotForm:Form{readonly AppSettings s=SettingsService.Load();EnvRules? rules;Snapshot? a;Snapshot? b;
 readonly TextBox projectBox=new(){Dock=DockStyle.Fill};readonly CheckBox drawingsBox=new(){Text="Include every drawing's WD_M (closed drawings only)",AutoSize=true,Anchor=AnchorStyles.Left,Checked=true};readonly Label aLabel=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};readonly Label bLabel=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};
 readonly TextBox output=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,Font=new Font("Consolas",9f)};readonly Label status=new(){Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};
 static string PathA=>Path.Combine(SettingsService.SnapshotFolder,"last_A.json");static string PathB=>Path.Combine(SettingsService.SnapshotFolder,"last_B.json");
 public SnapshotForm(string start){Text=BuildInfo.Title("setting snapshot and diff (locate ?[n] lines and WD_M attributes)");StartPosition=FormStartPosition.CenterParent;Size=new Size(1100,720);MinimumSize=new Size(800,520);projectBox.Text=start;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=6,Padding=new Padding(10)};root.ColumnStyles.Add(new(SizeType.Absolute,110));root.ColumnStyles.Add(new(SizeType.Percent,100));root.ColumnStyles.Add(new(SizeType.Absolute,120));root.ColumnStyles.Add(new(SizeType.Absolute,120));foreach(int h in new[]{34,30,34,34,0,44})root.RowStyles.Add(h==0?new(SizeType.Percent,100):new(SizeType.Absolute,h));
  root.Controls.Add(new Label{Text="Project (.wdp)",AutoSize=true,Anchor=AnchorStyles.Left},0,0);root.Controls.Add(projectBox,1,0);var browse=new Button{Text="Browse...",Dock=DockStyle.Fill};browse.Click+=(_,_)=>{using var d=new OpenFileDialog{Filter="AutoCAD Electrical project (*.wdp)|*.wdp",FileName=projectBox.Text};if(d.ShowDialog(this)==DialogResult.OK)projectBox.Text=d.FileName;};root.Controls.Add(browse,2,0);
  var help=new Label{AutoSize=true,Anchor=AnchorStyles.Left,ForeColor=Color.FromArgb(70,70,70),Text="Take A, change ONE setting in AutoCAD Electrical's Project Properties (and Drawing Properties if you want the WD_M side), save, take B, then Diff. The lines that moved are the ones to put in the rules JSON setting map."};root.Controls.Add(help,1,1);root.SetColumnSpan(help,3);
  root.Controls.Add(drawingsBox,1,2);var takeA=new Button{Text="Take A",Dock=DockStyle.Fill};var takeB=new Button{Text="Take B",Dock=DockStyle.Fill};root.Controls.Add(takeA,2,2);root.Controls.Add(takeB,3,2);
  var labels=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};labels.ColumnStyles.Add(new(SizeType.Percent,50));labels.ColumnStyles.Add(new(SizeType.Percent,50));labels.Controls.Add(aLabel,0,0);labels.Controls.Add(bLabel,1,0);root.Controls.Add(labels,1,3);var diff=new Button{Text="Diff A -> B",Dock=DockStyle.Fill};var swap=new Button{Text="B becomes A",Dock=DockStyle.Fill};root.Controls.Add(diff,2,3);root.Controls.Add(swap,3,3);
  root.Controls.Add(output,0,4);root.SetColumnSpan(output,4);
  var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3};footer.ColumnStyles.Add(new(SizeType.Percent,100));footer.ColumnStyles.Add(new(SizeType.Absolute,120));footer.ColumnStyles.Add(new(SizeType.Absolute,100));var save=new Button{Text="Save diff...",Dock=DockStyle.Fill};var close=new Button{Text="Close",Dock=DockStyle.Fill};footer.Controls.Add(status,0,0);footer.Controls.Add(save,1,0);footer.Controls.Add(close,2,0);root.Controls.Add(footer,0,5);root.SetColumnSpan(footer,4);Controls.Add(root);
  takeA.Click+=(_,_)=>{a=Take();if(a is not null){Persist(a,PathA);ShowState();}};takeB.Click+=(_,_)=>{b=Take();if(b is not null){Persist(b,PathB);ShowState();}};diff.Click+=(_,_)=>Diff();swap.Click+=(_,_)=>{if(b is null)return;a=b;b=null;Persist(a,PathA);try{File.Delete(PathB);}catch{}ShowState();};
  save.Click+=(_,_)=>{using var d=new SaveFileDialog{Filter="Text (*.txt)|*.txt",FileName="LSE_Env_snapshot_diff_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".txt"};if(d.ShowDialog(this)==DialogResult.OK){try{File.WriteAllText(d.FileName,output.Text);}catch(Exception ex){MessageBox.Show(ex.Message,"LSE_Env");}}};close.Click+=(_,_)=>Close();CancelButton=close;
  Shown+=(_,_)=>{try{rules=RulesService.Load(s.RulesConfigPath);}catch(Exception ex){status.Text="Rules could not be loaded: "+ex.Message;ErrorService.Show(this,"Loading rules",ex);}a=Restore(PathA);b=Restore(PathB);ShowState();if(a is null)status.Text="Take snapshot A of the project as it is now.";};}
 Snapshot? Take(){try{string wdp=projectBox.Text.Trim();if(!File.Exists(wdp))throw new FileNotFoundException("Project file was not found.",wdp);UseWaitCursor=true;try{status.Text="Reading...";status.Refresh();var snap=EnvironmentService.Take(wdp,rules??RulesService.Load(s.RulesConfigPath),AcadeBridgeService.Bridge(rules??RulesService.Load(s.RulesConfigPath)),drawingsBox.Checked);status.Text=$"Snapshot taken: {snap.Wdp.Count} project line(s), {snap.Drawings.Count} drawing(s)"+(snap.Notes.Count>0?"; "+snap.Notes.Count+" drawing(s) skipped":"");return snap;}finally{UseWaitCursor=false;}}catch(Exception ex){status.Text="Failed: "+ex.Message;ErrorService.Show(this,"Take snapshot",ex);return null;}}
 void ShowState(){aLabel.Text=a is null?"A: (none)":$"A: {a.Taken:yyyy-MM-dd HH:mm:ss}  {Path.GetFileName(a.WdpPath)}  {a.Wdp.Count} lines, {a.Drawings.Count} drawings";bLabel.Text=b is null?"B: (none)":$"B: {b.Taken:yyyy-MM-dd HH:mm:ss}  {Path.GetFileName(b.WdpPath)}  {b.Wdp.Count} lines, {b.Drawings.Count} drawings";
  if(a is not null&&b is null)output.Text=string.Join(Environment.NewLine,new[]{"Snapshot A (project lines):"}.Concat(a.Wdp.Select(kv=>"  "+kv.Key+" = "+kv.Value)).Concat(a.Drawings.SelectMany(d=>new[]{"","Snapshot A "+Path.GetFileName(d.Key)+" WD_M:"}.Concat(d.Value.Select(kv=>"  "+kv.Key+" = "+kv.Value)))).Concat(a.Notes.Select(n=>"  note: "+n)));}
 void Diff(){if(a is null||b is null){status.Text="Take both snapshots first.";return;}var r=rules??RulesService.Load(s.RulesConfigPath);var lines=EnvironmentService.Diff(a,b,r);output.Text=string.Join(Environment.NewLine,new[]{$"Diff A ({a.Taken:HH:mm:ss}) -> B ({b.Taken:HH:mm:ss}) for {a.WdpPath}",""}.Concat(lines).Concat(new[]{"","Map a changed line in the rules JSON: \"property\": <n> for a ?[n] line, \"wdm\": \"<TAG>\" for a WD_M attribute, then set \"confidence\": \"verified\"."}));status.Text=lines.Count+" difference(s).";}
 static void Persist(Snapshot snap,string path){try{Directory.CreateDirectory(SettingsService.SnapshotFolder);File.WriteAllText(path,JsonSerializer.Serialize(snap,SettingsService.Json));}catch{}}
 static Snapshot? Restore(string path){try{return File.Exists(path)?JsonSerializer.Deserialize<Snapshot>(File.ReadAllText(path),SettingsService.Json):null;}catch{return null;}}
}
